#!/usr/bin/env python3
"""Exercise complete legacy verifier with libc refusal and real mapped native allocations."""
from pathlib import Path
import argparse,subprocess,os
ROOT=Path(__file__).resolve().parents[1]
JDK=Path('/opt/homebrew/opt/openjdk@25/libexec/openjdk.jdk/Contents/Home')
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--class-path',required=True)
parser.add_argument('classes',nargs='+')
args=parser.parse_args();work=ROOT/'build/java25';source=ROOT/'.tools/java25/openjdk/src'
(work/"VerifyPoolCheck.java").write_text('public class VerifyPoolCheck {\n static native int verify(Class<?> type,int major,int mode);\n public static void main(String[] args)throws Exception {System.load(args[0]);for(String name:java.util.Arrays.copyOfRange(args,1,args.length)){Class<?> type=Class.forName(name,false,ClassLoader.getSystemClassLoader());int major;try(var input=new java.io.DataInputStream(type.getResourceAsStream("/"+name.replace(".","/")+".class"))){if(input.readInt()!=0xCAFEBABE)throw new AssertionError("class magic");input.readUnsignedShort();major=input.readUnsignedShort();}if(major>50)throw new IllegalArgumentException("Use the modern JVM verifier for class version "+major+": "+name);for(int mode:new int[]{0,1,2,3,4,5,6}){int result=verify(type,major,mode);int expected=mode<2||mode==6?1:2;if(result!=expected)throw new AssertionError(name+" mode "+mode+" result "+result);}System.out.println("PASS real legacy verifier: "+name);}}\n}\n')
(work/"verifier-native-bridge.c").write_text('#include <jni.h>\n#include <stdlib.h>\n#include <stdio.h>\n#include <assert.h>\n#include <errno.h>\n#include <sys/mman.h>\nstatic int deny_heap,budget;static long live;\nvoid *ps5_test_malloc(size_t bytes){return deny_heap?NULL:malloc(bytes);}\nvoid *ps5_test_map(void *p,size_t n,int prot,int flags,int fd,off_t off){if(budget==0){errno=ENOMEM;return MAP_FAILED;}if(budget>0)--budget;void *r=mmap(p,n,prot,flags,fd,off);if(r!=MAP_FAILED)++live;return r;}\nint ps5_test_unmap(void *p,size_t n){int r=munmap(p,n);assert(!r);--live;return r;}\nextern void JNU_PS5SetVerifierSmallReserveEnabled(int);\nextern jboolean VerifyClassForMajorVersion(JNIEnv*,jclass,char*,jint,jint);\nJNIEXPORT jint JNICALL Java_VerifyPoolCheck_verify(JNIEnv *env,jclass self,jclass type,jint major,jint mode){char error[4096]={0};deny_heap=mode!=0;budget=mode==6?0:mode<2?-1:mode-2;JNU_PS5SetVerifierSmallReserveEnabled(mode==6);int result=VerifyClassForMajorVersion(env,type,error,sizeof(error),major);assert(live==0);return result;}\n')
incs=[JDK/'include',JDK/'include/darwin',source/'java.base/share/native/libjava',source/'java.base/unix/native/libjava',source/'hotspot/share/include',source/'hotspot/os/posix/include',source/'java.base/share/native/include']
common=['clang','-std=c11','-fsanitize=undefined',*['-I'+str(p) for p in incs]]
subprocess.run([*common,'-D__PROSPERO__','-DNDEBUG','-D_LITTLE_ENDIAN','-Dmalloc=ps5_test_malloc','-Dmmap=ps5_test_map','-Dmunmap=ps5_test_unmap','-c',str(source/'java.base/share/native/libverify/check_code.c'),'-o',str(work/'verifier-native.o')],check=True)
subprocess.run([*common,'-c',str(work/'verifier-native-bridge.c'),'-o',str(work/'verifier-native-bridge.o')],check=True)
subprocess.run(['clang','-fsanitize=undefined','-dynamiclib','-undefined','dynamic_lookup',str(work/'verifier-native.o'),str(work/'verifier-native-bridge.o'),'-o',str(work/'libverify-native-host.dylib')],check=True)
subprocess.run([str(JDK/'bin/javac'),'-d',str(work),str(work/'VerifyPoolCheck.java')],check=True)
subprocess.run([str(JDK/'bin/java'),'--enable-native-access=ALL-UNNAMED','-cp',str(work)+':'+args.class_path,'VerifyPoolCheck',str(work/'libverify-native-host.dylib'),*args.classes],check=True,env={**os.environ,'UBSAN_OPTIONS':'halt_on_error=1:handle_segv=0:handle_sigbus=0:handle_sigfpe=0'})
